<script setup lang="ts">
import { ref } from 'vue'; import ToolPageHeader from '@/components/tool/ToolPageHeader.vue'; import ToolDocumentation from '@/components/tool/ToolDocumentation.vue'; import { describeCron, nextCronRuns } from '../lib/cron'
const expression=ref('*/5 * * * *');const runs=ref<string[]>([]);const description=ref('');const error=ref('')
function parse(){try{error.value='';runs.value=nextCronRuns(expression.value,10);description.value=describeCron(expression.value)}catch(e){runs.value=[];description.value='';error.value=e instanceof Error?e.message:'解析失败'}}
const docs=[{title:'字段顺序',content:'使用标准五字段 Cron：分钟 小时 日期 月份 星期。'},{title:'执行时间',content:'未来时间按浏览器当前时区展示，同时保留 ISO 时间便于核对。'},{title:'兼容范围',content:'解析器支持常见通配符、范围、列表和步长；不同调度平台的扩展语法可能不同。'}]
</script>
<template><div class="sr-page"><ToolPageHeader category="日期时间" title="Cron 表达式解析" description="校验 Cron 表达式并预览未来十次执行时间。" :tags="['Cron','定时任务']"/><section class="tool-box sr-panel"><label class="sr-tool-label">Cron 表达式</label><el-input v-model="expression" placeholder="例如 */5 * * * *" @keyup.enter="parse"/><div class="presets"><el-button v-for="item in [['每 5 分钟','*/5 * * * *'],['每小时','0 * * * *'],['每天零点','0 0 * * *'],['每周一','0 0 * * 1']]" :key="item[0]" @click="expression=item[1]">{{item[0]}}</el-button></div><div class="actions"><el-button class="sr-primary-button" type="primary" @click="parse">开始解析</el-button><el-button @click="expression='';runs=[];description='';error=''">清空</el-button></div><p v-if="error" class="error">{{error}}</p></section><section v-if="runs.length" class="result sr-panel"><h2>{{description}}</h2><ol><li v-for="run in runs" :key="run"><code>{{new Date(run).toLocaleString()}}</code><span>{{run}}</span></li></ol></section><ToolDocumentation :sections="docs"/></div></template>
<style scoped lang="scss">.tool-box,.result{padding:20px}.tool-box .el-input{margin-top:9px}.presets,.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.error{color:#c43f3f}.result{margin-top:14px}.result h2{margin:0 0 12px;color:#218a5a;font-size:15px}.result ol{margin:0;padding-left:24px}.result li{display:grid;grid-template-columns:180px 1fr;gap:12px;padding:8px;border-bottom:1px solid var(--sr-border)}.result span{color:var(--sr-text-muted);font-size:12px}@media(max-width:650px){.result li{grid-template-columns:1fr}}</style>
